func revalidateVoiceTells(ctx context.Context, db *sql.DB, item parkedReviewItem, logger *zap.Logger) revalidationVerdict {
	pageID := specString(item.Spec, "page_id")
	if pageID == "" {
		return revalidationVerdict{Verdict: revalidationUnknown, Reason: "spec names no page_id ... the item_key prefix is deliberately not parsed for it"}
	}
	gate, err := checks.LoadVoiceGate(ctx, db, item.SiteID)
	if err != nil { return revalidationVerdict{Verdict: revalidationUnknown, ...} }
	if gate == nil {
		return revalidationVerdict{Verdict: revalidationUnknown, Reason: "site has no enabled voice_gate, so the standard this finding was measured against no longer exists; opting out is not evidence the copy was fixed"}
	}
	scans, err := checks.ScanVoiceTells(ctx, db, item.SiteID, pageID, gate, logger)
	if err != nil { return revalidationVerdict{Verdict: revalidationUnknown, ...} }
	var scan *checks.VoicePageScan
	for _, s := range scans { if s.PageID == pageID { scan = s; break } }
	return voiceTellsVerdict(pageID, scan)
}

func voiceTellsVerdict(pageID string, scan *checks.VoicePageScan) revalidationVerdict {
	if scan == nil {
		return revalidationVerdict{Verdict: revalidationUnknown, Reason: "page is absent, not active/deployed, or has no rendered components ... an unserved page is not evidence the prose was fixed"}
	}
	if scan.ComponentsExamined == 0 {
		return revalidationVerdict{Verdict: revalidationUnknown, Reason: "every rendered component on this page is human-locked ... an empty finding list here means the scan read nothing"}
	}
	if len(scan.Findings) > 0 {
		return revalidationVerdict{Verdict: revalidationStillHolds, ...}
	}
	if scan.ComponentsSkippedLocked > 0 {
		return revalidationVerdict{Verdict: revalidationUnknown, Reason: "the N component(s) scanned are clean, but M human-locked component(s) were not read, and the reported tells may sit in those"}
	}
	return revalidationVerdict{Verdict: revalidationResolved, ...}
}

